{
  "status": "ok",
  "data": {
    "as_of": "2018-05-24",
    "lookback_days": 365,
    "n_entries_total": 53,
    "n_entries_visible": 12,
    "entries": [
      {
        "entry_date": "2017-08-14",
        "body": "Trump signs memorandum directing USTR to investigate China's IP and technology-transfer practices under Section 301. USTR investigation initiated."
      },
      {
        "entry_date": "2017-11-08",
        "body": "Trump visits Beijing; large package of commercial deals announced (many MOUs). No substantive concessions on structural IP / tech-transfer issues."
      },
      {
        "entry_date": "2018-01-22",
        "body": "Trump approves Section 201 safeguard tariffs on solar panels and washing machines (China among suppliers hit). First major tariff action of the administration."
      },
      {
        "entry_date": "2018-03-01",
        "body": "Trump announces plan to impose 25% tariff on steel and 10% on aluminum imports (Section 232). Global scope; China is a smaller direct supplier share than some other exporters."
      },
      {
        "entry_date": "2018-03-02",
        "body": "Trump tweets: \"trade wars are good, and easy to win.\""
      },
      {
        "entry_date": "2018-03-08",
        "body": "Trump signs Section 232 proclamations imposing the steel (25%) and aluminum (10%) tariffs."
      },
      {
        "entry_date": "2018-03-22",
        "body": "USTR releases Section 301 report finding China's IP/tech-transfer practices unreasonable or discriminatory. Trump signs presidential memorandum directing tariffs on Chinese imports, a WTO case, and investment restrictions. USTR to publish a proposed tariff list."
      },
      {
        "entry_date": "2018-04-02",
        "body": "China imposes retaliatory tariffs on about $3B of US goods (pork, fruit, nuts, wine, and related items) in response to Section 232 steel/aluminum tariffs."
      },
      {
        "entry_date": "2018-04-03",
        "body": "USTR publishes proposed Section 301 tariff list: ~1,300 Chinese product lines (~$50B), targeting aerospace, ICT, robotics, machinery and related sectors. Public comment process opens."
      },
      {
        "entry_date": "2018-04-04",
        "body": "China announces proposed retaliatory tariffs on ~$50B of US goods (including soybeans, automobiles, and aircraft) in response to the Section 301 list."
      },
      {
        "entry_date": "2018-04-16",
        "body": "US Commerce Department bans ZTE from buying US components (denial order). ZTE faces operational shutdown. Major non-tariff escalation."
      },
      {
        "entry_date": "2018-05-19",
        "body": "US and China release joint statement after talks: China agrees to \"significantly increase\" purchases of US goods and services. Mnuchin says trade war is \"on hold.\" Markets rally."
      }
    ]
  }
}

